//! The root certificate table: Mozilla's trusted TLS server roots.
//!
//! Plain data, not part of any proof. [`data::ROOTS`] is generated by
//! `cargo xtask tables` (`xtask/src/roots.rs`) from NSS's `certdata.txt`,
//! vendored under `data/nss-<commit>/`; the crate's README states which
//! roots it holds and what it carries for each. Nothing here decides trust:
//! a verifier takes a root from the table and applies the checks of
//! RFC 5280 §6.1 to the chain it was given.

/// One root certificate.
#[derive(Debug, Clone, Copy)]
pub struct Root {
    /// NSS's `CKA_LABEL`, the name NSS gives the root.
    pub label: &'static str,
    /// The complete DER `Certificate` (`CKA_VALUE`).
    pub der: &'static [u8],
    /// SHA-256 of [`Root::der`].
    pub sha256: [u8; 32],
    /// NSS's `CKA_NSS_SERVER_DISTRUST_AFTER` as the `UTCTime` text
    /// `YYMMDDHHMMSSZ`, if the root sets one: server certificates issued
    /// after that time must not be trusted through this root. Carried from
    /// NSS, not applied here.
    pub server_distrust_after: Option<&'static str>,
}

// The generated file is long lines of byte values; rustfmt would rewrap it.
#[rustfmt::skip]
pub mod data;

pub use data::ROOTS;
